one;padding:2px;background:#fff}.product-card:hover .actions{display:flex}.table-product{display:flex;align-items:center;gap:10px}.table-product>div{width:48px;height:40px}.table-product span{display:grid}.table-product small{color:#7a8799}@media(max-width:1350px){.grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:760px){.page-title{flex-direction:column}.toolbar{grid-template-columns:1fr 1fr}.toolbar>:first-child{grid-column:1/-1}.grid{grid-template-columns:1fr}.product-metrics div{min-width:0;flex:1;padding:12px}.product-metrics{overflow:auto}}
.image{min-height:154px;overflow:hidden}.image :deep(.visual),.image :deep(.visual img){min-height:0}
</style>
